package com.android.messaging.ui.conversation;
import android.graphics.Canvas;import android.graphics.ColorFilter;import android.graphics.Paint;import android.graphics.Path;import android.graphics.Rect;import android.graphics.RectF;import android.graphics.drawable.Drawable;
public final class MessageBubbleBackground extends Drawable {private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final boolean incoming;private final float r,arrow;public MessageBubbleBackground(int color,boolean incoming,float density){p.setColor(color);this.incoming=incoming;r=12*density;arrow=7*density;}@Override public void draw(Canvas c){Rect b=getBounds();float l=incoming?arrow:0,rgt=incoming?b.right:b.right-arrow;RectF box=new RectF(l,b.top,rgt,b.bottom);c.drawRoundRect(box,r,r,p);Path x=new Path();float cy=b.bottom-14; if(incoming){x.moveTo(arrow,cy-5);x.lineTo(0,cy+4);x.lineTo(arrow,cy+4);}else{x.moveTo(b.right-arrow,cy-5);x.lineTo(b.right,cy+4);x.lineTo(b.right-arrow,cy+4);}x.close();c.drawPath(x,p);}@Override public void setAlpha(int a){p.setAlpha(a);invalidateSelf();}@Override public void setColorFilter(ColorFilter f){p.setColorFilter(f);invalidateSelf();}@Override public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}}
